import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.util.*;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.Charsets;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.equals(CharSequence, CharSequence)
 */
public class StringUtils_equals_TriageGen0Test {









    @Test
    public void testEquals_OneStringOneStringBuilder_NotString() {
        String cs1 = "hello";
        StringBuilder cs2 = new StringBuilder("hello");
        // Covers: The logic falls through to the last return statement 
        // because (cs1 instanceof String && cs2 instanceof String) is false.
        // The last line: return false && CharSequenceUtils.regionMatches(...)
        // Since it starts with 'false &&', it will always return false.
        assertFalse(StringUtils.equals(cs1, cs2));
    }




}

